package com.jobmatcher.service;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.util.List;class JobServiceTest {@Test void ranksAndExcludesJobsWithoutAnyMatchedSkill(){var result=new JobService().match(List.of("python","sql","statistics"));assertFalse(result.isEmpty());assertEquals("Data Scientist",result.get(0).job().title());assertEquals(60,result.get(0).score());assertTrue(result.stream().allMatch(x->!x.matched().isEmpty()));}}
